try{require __DIR__.'/../app/bootstrap.php';$method=$_SERVER['REQUEST_METHOD'];$uri=trim((string)parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),'/');$pos=strpos($uri,'api/');$route=$pos===false?'':substr($uri,$pos+4);
