 if(preg_match('~^decisions/(\d+)$~',$route,$m)&&$method==='GET'){$st=$db->prepare('SELECT * FROM company_decisions WHERE id=?');$st->execute([(int)$m[1]]);$decision=$st->fetch();if(!$decision)jsonResponse(['error'=>'최종 판단을 찾을 수 없습니다.'],404);foreach(['reasons_json','risks_json','required_actions_json','current_scorecard_json','improvement_plan_json','to_be_json','kpis_json']as$key)$decision[str_replace('_json','',$key)]=json_decode((string)$decision[$key],true);jsonResponse(['data'=>$decision]);}
